		if got, ok := e.twoDone(D, D); ok {
			return e.twolcs(D, D, got)
		}
		e.setForward(D+1, -(D + 1), e.getForward(D, -D))
		e.setForward(D+1, D+1, e.getForward(D, D)+1)
