package analyzer

import (
	"fmt"
	"go/token"
	"sort"
	"strings"

	"declscope/internal/checker"
)

// finding is a report before ignores and the baseline are consulted.
type finding struct {
	rule    string
	pos     token.Pos
	message string
	related []checker.RelatedInformation
	fix     *checker.SuggestedFix
