	if su := byDir[filepath.Dir(path)]; su != nil && (f.Name.Name == su.pkg.Name) {
		names := st.ownNames[su]
		if names == nil {
			names = make(map[string]bool)
			st.ownNames[su] = names
		}
		ast.Inspect(f, func(n ast.Node) bool {
			if id, ok := n.(*ast.Ident); ok {
				names[id.Name] = true
			}
			return true
		})
		return
	}
	imports := make(map[string]*shrinkUnit)
	for _, is := range f.Imports {
		p, err := strconv.Unquote(is.Path.Value)
		if err != nil {
			continue
		}
		su := st.byPath[p]
		if su == nil {
			continue
		}
		name := su.pkg.Name
		if is.Name != nil {
			name = is.Name.Name
		}
		imports[name] = su
	}
	if len(imports) == 0 {
		return
	}
	ast.Inspect(f, func(n ast.Node) bool {
		sel, ok := n.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		x, ok := sel.X.(*ast.Ident)
		if !ok {
			return true
		}
		su := imports[x.Name]
		if su == nil {
			return true
		}
		obj := su.pkg.Types.Scope().Lookup(sel.Sel.Name)
		if obj == nil {
			return true
		}
		if c := st.byObj[obj.Pos()]; c != nil {
			c.external = true
		}
		walkNamed(obj.Type(), map[types.Type]bool{}, func(tn *types.TypeName) {
			st.mayUse[tn.Pos()] = true
		})
		if tn, ok := obj.(*types.TypeName); ok {
			st.mayUse[tn.Pos()] = true
		}
		return true
	})
