func (m *model) changesFindings(dir *directive, base []*finding) bool {
	m.resolveScopes(map[*directive]bool{dir: true})
	defer m.resolveScopes(nil)
	others := func(fs []*finding) []*finding {
		var out []*finding
		for _, f := range fs {
			if f.dir != dir {
				out = append(out, f)
			}
		}
		return out
	}
	after := others(m.declFindings(true))
	before := others(base)
	if len(after) != len(before) {
		return true
	}
	for i := range after {
		a, b := after[i], before[i]
		if a.rule != b.rule || a.pos != b.pos || a.message != b.message {
			return true
		}
	}
	return false
}

