"""Qualify rename stress: methods filed away, embedding, interfaces, conflicts. txtar to stdout."""
import random
import sys

seed = int(sys.argv[1])
R = random.Random(seed)
NAMES = ["run", "stop", "item", "value", "name", "id", "load", "save", "get", "set", "close", "key", "data"]
FILES = ["user.go", "order.go", "store.go", "api.go"]

files = {f: ["package p", ""] for f in FILES}
types_ = []
for ti in range(R.randint(2, 4)):
    f = R.choice(FILES)
    t = R.choice(["t", "s", "box", "item", "holder", "node"]) + str(ti)
    if R.random() < 0.3:
        t = t.capitalize()
    fields = []
    for _ in range(R.randint(0, 2)):
        x = R.choice(NAMES + [n.capitalize() for n in NAMES] + ["userRun", "orderID", "storeKey"])
        if x not in fields:
            fields.append(x)
    emb = []
    if types_ and R.random() < 0.5:
        emb.append(R.choice(types_)[0])
    files[f].append("type %s struct {\n%s\n}" % (t, "\n".join(["\t" + e for e in emb] + ["\t%s int" % x for x in fields])))
    meths = []
    for _ in range(R.randint(0, 3)):
        m = R.choice(NAMES + [n.capitalize() for n in NAMES])
        if m in fields or m in meths:
            continue
        meths.append(m)
        mf = R.choice(FILES)
        files[mf].append("func (%s%s) %s() {}" % ("*" if R.random() < 0.4 else "", t, m))
    types_.append((t, fields, meths, emb))
for ii in range(R.randint(0, 2)):
    f = R.choice(FILES)
    ms = R.sample(NAMES + ["userRun", "orderLoad", "storeSave", "apiGet"], R.randint(1, 2))
    files[f].append("type %s interface {\n%s\n}" % ("i" + str(ii), "\n".join("\t%s()" % m for m in ms)))
for f in FILES:
    uses = []
    for t, fields, meths, emb in R.sample(types_, min(2, len(types_))):
        if meths and R.random() < 0.6:
            uses.append("(&%s{}).%s()" % (t, R.choice(meths)))
        if fields and R.random() < 0.5:
            uses.append("_ = %s{}.%s" % (t, R.choice(fields)))
    if uses:
        files[f].append("func %sUse() {\n%s\n}" % (f[:-3], "\n".join("\t" + u for u in uses)))
print("-- go.mod --\nmodule example.com/m\n\ngo 1.22\n")
print("-- .declscope.yaml --\nrules:\n  naming:\n    qualify: always\n    exported: %s\n  boundary: off\n" % R.choice(["true", "false"]))
for f in FILES:
    print("-- p/%s --\n%s\n" % (f, "\n\n".join(files[f])))
print("-- @cmd --")
print("go build ./... >/dev/null 2>&1 || echo BROKEN_INPUT; $X ./...; echo \"exit $?\"")
print("$X -fix ./...; echo \"exit $?\"; go build ./... && echo BUILD_OK; cat p/*.go")

